@js:
var list = [],
arr = result.toArray();
arr.forEach((a,i)=>{
	if(/javascript/i.test(arr[i])){
		//修补章节链接缺失 
		prevurl=arr[i-1].attr('href');
		d=java.ajax('https://www.qiuxiaxs.com'+prevurl)	; href=org.jsoup.Jsoup.parse(d).select(".next").attr("href");
		name=a.text();
		list.push({text:name,href:href});
		}
		else{
			name=a.text(),
			url=arr[i].attr("href");
			list.push({text:name,href:url});
			}
	});
java.log(JSON.stringify(list))
list;

